// variant of https://www.shadertoy.com/view/flGSRV

#define rot(a)          mat2(cos(a+vec4(0,11,33,0)))  // rotation

void mainImage(out vec4 O, vec2 U)
{
    float t=9., m=t; 

    vec3  R = iResolution, Y = vec3(0,1,0),
          D = normalize(vec3((U+U-R.xy)/R.y, -3.)),   // ray direction
          p = vec3(0,0,240./exp2(2.*iMouse.y/R.y)), q,_q,a, // marching point along ray 
          M = iMouse.z > 0. ? iMouse.xyz/R -.5: vec3(10,12,0)/1e2*cos(.3*iTime+vec3(0,11,0))+vec3(0,.12,0); 

    for ( O=vec4(1); O.x > 0. && t > .005; O-=.01 ) {
        q = p,
        q.yz *= rot(.5-6.3*M.y),                      // rotations
        q.xz *= rot(-6.3*M.x), 
        a = abs(q), 
        q = fract(q)-.5,                              // cells
        t = max( length(q)-.2,                        // spheres
                 max(a.x, max(a.y,a.z))-50. ),        // clamp to cube
        t < m ? _q=p, m = t : m,

        p += .4*t*D;                                  // step forward = dist to obj
    }
    O.rgb *= .5+.5*_q/50.;
}
